def prepare_existing_data(apps, schema_editor):
    DriverProfile=apps.get_model('core','DriverProfile')
    Issue=apps.get_model('core','Issue')
    Notification=apps.get_model('core','Notification')
    UserProfile=apps.get_model('core','UserProfile')
    # Keep one driver per vehicle before converting the relation to OneToOne.
    seen=set()
    for d in DriverProfile.objects.exclude(vehicle__isnull=True).order_by('vehicle_id','id'):
        if d.vehicle_id in seen:
            d.vehicle_id=None; d.save(update_fields=['vehicle'])
        else:
            seen.add(d.vehicle_id)
    # Preserve historical snapshots so later part/driver edits do not rewrite history.
    for i in Issue.objects.select_related('part','vehicle').all():
        if not i.part_name_snapshot: i.part_name_snapshot=i.part.name
        if not i.part_code_snapshot: i.part_code_snapshot=i.part.code
        if not i.unit_snapshot: i.unit_snapshot=i.part.unit
        if not i.odometer: i.odometer=i.vehicle.current_mileage
        if not i.driver_id:
            existing_driver=DriverProfile.objects.filter(vehicle_id=i.vehicle_id).order_by('id').first()
            if existing_driver: i.driver_id=existing_driver.pk
        if i.driver_id and not i.driver_name_snapshot:
            i.driver_name_snapshot=DriverProfile.objects.filter(pk=i.driver_id).values_list('full_name',flat=True).first() or ''
        i.save(update_fields=['part_name_snapshot','part_code_snapshot','unit_snapshot','odometer','driver_id','driver_name_snapshot'])
    # Existing driver notifications remain valid; attach their company.
    for n in Notification.objects.select_related('driver','driver__company','driver__user').all():
        if not n.company_id and n.driver_id: n.company_id=n.driver.company_id
        if not n.recipient_id and n.driver_id:
            n.recipient_id=UserProfile.objects.filter(user_id=n.driver.user_id).values_list('pk',flat=True).first()
        n.save(update_fields=['company_id','recipient_id'])


def create_maintenance_from_legacy(apps, schema_editor):
    ServiceRecord=apps.get_model('core','ServiceRecord')
    MaintenanceSchedule=apps.get_model('core','MaintenanceSchedule')
    for old in ServiceRecord.objects.all():
        MaintenanceSchedule.objects.get_or_create(
            vehicle_id=old.vehicle_id,
            name=old.service_type,
            defaults={
                'interval_km':old.interval if old.kind != 'DAY' else 0,
                'last_mileage':old.last_mileage,
                'last_date':old.last_date,
                'active':True,
            },
        )


